import clsx from 'clsx';

function Button({ active, disabled }) {
  return (
    <button
      className={clsx('px-4 py-2 rounded', {
        'bg-blue-500 text-white': active,
        'bg-gray-300 text-gray-500': !active,
        'opacity-50 cursor-not-allowed': disabled
      })}
    >
      Click me
    </button>
  );
}
